import { spreadsheetValue } from "./safety.ts";

// RFC 4180: quote fields containing delimiters, quotes or line breaks; double embedded quotes.
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

export function csvRecord(values: string[]): string {
  const cells = values.map(value => csvField(spreadsheetValue(value)));
  // Serialize one record.
  return cells.join(",") + "\r\n";
}
EOF
cat >> tests/export.test.ts <<'EOF'
test("quotes delimiters, quotes and line breaks so every record keeps four columns",()=>{
  assert.equal(
    exportContacts([
      {id:"c3",name:"Doe, Jane",company:"Acme, Inc",email:"jane@example.test"},
      {id:"c4",name:"Sam",company:"The \"Best\" Co\r\nLtd",email:"=cmd,x"},
    ]),
    "id,name,company,email\r\n"+
    "c3,Doe; Jane,\"Acme, Inc\",jane@example.test\r\n"+
    "c4,Sam,\"The \"\"Best\"\" Co\r\nLtd\",\"'=cmd,x\"\r\n",
  );
});
EOF
